using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) Strongly-typed metadata: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Type  : {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");

Person? p = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"Round-trip : {p}");

// 2) Probe without throwing: TryGetTypeInfo returns false if metadata isn't available
//    Use a resolver that only knows about int, so Person lookup will fail.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
        .WithAddedModifier(ti =>
        {
            // allow only System.Int32 metadata
            if (ti.Type != typeof(int))
                throw new NotSupportedException();
        })
};

bool found = limited.TryGetTypeInfo(typeof(int), out JsonTypeInfo? intInfo);
Console.WriteLine($"\nint  found? {found} -> {intInfo?.Type.Name}");

bool notFound = limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? missing);
Console.WriteLine($"Person found? {notFound} -> {missing?.Type.Name ?? "(null)"}");

record Person(string Name, int Age);

