{
    private static readonly DefaultJsonTypeInfoResolver s_default = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
        => type == typeof(int) ? s_default.GetTypeInfo(type, options) : null;
}

